function redact(text) {
  const cfg = {"stoplist": ["after", "approve", "april", "august", "avenue", "baker", "bank", "boulevard", "bristol", "claude", "client", "court", "csv", "daily", "dear", "december", "division", "draft", "drive", "every", "february", "friday", "from", "gmail", "google", "hello", "invoice", "january", "july", "june", "king", "lane", "london", "make", "manchester", "march", "market", "may", "monday", "monthly", "morning", "notes", "november", "oak", "october", "once", "oregon", "park", "pdf", "pine", "place", "please", "portland", "river", "road", "sales", "saturday", "seattle", "september", "sheet", "sheets", "square", "station", "street", "subject", "sunday", "tax", "thanks", "that", "then", "this", "thursday", "today", "tuesday", "way", "wednesday", "weekly", "whatsapp", "when", "willow", "xero"], "patterns": {"email": ["[A-Za-z0-9._%+\\-]+@[A-Za-z0-9.\\-]+\\.[A-Za-z]{2,}"], "phone": ["\\+\\d{1,3}(?:[\\s\\-.]?\\(?\\d{1,4}\\)?){2,5}", "(?:\\(\\d{3}\\)|\\b\\d{3})[\\s.\\-]\\d{3}[\\s.\\-]\\d{4}\\b", "\\b0\\d{2,4}(?:[\\s\\-]\\d{3,4}){2}\\b"], "amount": ["(?:USD|GBP|EUR|CAD)\\s+\\d{1,3}(?:,\\d{3})*(?:\\.\\d{2})?", "[$\u00a3\u20ac]\\s?\\d{1,3}(?:,\\d{3})*(?:\\.\\d{2})?", "\\b\\d{1,3}(?:,\\d{3})*(?:\\.\\d{2})?\\s+dollars\\b"], "address": ["\\b\\d{1,5}\\s+(?:[A-Z][A-Za-z]*\\.?\\s+){1,6}(?:Street|St|Avenue|Ave|Road|Rd|Boulevard|Blvd|Lane|Ln|Drive|Dr|Way|Court|Ct|Place|Pl)\\b(?:,\\s*[A-Z][a-z]+(?:\\s+[A-Z][a-z]+)*)?(?:,\\s*[A-Z]{2})?(?:\\s+\\d{5}(?:-\\d{4})?)?(?:\\s+[A-Z]{1,2}\\d[A-Z\\d]?\\s*\\d[A-Z]{2})?"], "name_title": ["\\b(?:Mr|Mrs|Ms|Mx|Dr|Prof)\\.?\\s+[A-Z][a-z]+(?:\\s+[A-Z][a-z]+){0,2}\\b"], "name_greeting": ["\\b(?:Hi|Hello|Dear|Hey)\\s+[A-Z][a-z]{2,}\\b"]}, "namePair": "\\b[A-Z][a-z]{2,}(?:-[A-Z][a-z]+)?\\s+[A-Z][a-z]{2,}(?:-[A-Z][a-z]+)?\\b", "order": ["email", "phone", "amount", "address", "name_title", "name_greeting", "name_pair"]};

  const priority = {};
  cfg.order.forEach((k, i) => { priority[k] = i; });
  const stop = new Set(cfg.stoplist);
  function collect(reSrc, kind, spans) {
    const re = new RegExp(reSrc, 'g');
    let m;
    while ((m = re.exec(text)) !== null) {
      if (m[0].length === 0) { re.lastIndex++; continue; }
      spans.push({ start: m.index, end: m.index + m[0].length, kind });
    }
  }
  const spans = [];
  Object.keys(cfg.patterns).forEach(kind => {
    cfg.patterns[kind].forEach(src => collect(src, kind, spans));
  });
  collect(cfg.namePair, 'name_pair', spans);
  const kept = [];
  spans.filter(s => {
    if (s.kind !== 'name_pair') return true;
    const words = (text.slice(s.start, s.end).match(/[A-Za-z][A-Za-z'\-]*/g) || []);
    return words.length >= 2 && words.every(w => !stop.has(w.toLowerCase()));
  }).sort((a, b) => (priority[a.kind] - priority[b.kind]) || ((b.end - b.start) - (a.end - a.start)) || (a.start - b.start))
    .forEach(span => {
      if (kept.some(prev => !(span.end <= prev.start || span.start >= prev.end))) return;
      kept.push(span);
    });
  kept.sort((a, b) => a.start - b.start);
  let out = '';
  let cursor = 0;
  const mapping = {};
  const counts = {};
  kept.forEach(span => {
    out += text.slice(cursor, span.start);
    const kind = span.kind.startsWith('name') ? 'name' : span.kind;
    counts[kind] = (counts[kind] || 0) + 1;
    const token = '[' + kind.toUpperCase() + '_' + counts[kind] + ']';
    mapping[token] = text.slice(span.start, span.end);
    out += token;
    cursor = span.end;
  });
  out += text.slice(cursor);
  return { text: out, mapping, counts };
}

const item = $input.first().json;
const raw = [item.subject, item.text, item.body, item.snippet].filter(Boolean).join('\n');
const result = redact(raw);
if (/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/.test(result.text)) {
  throw new Error('Redaction left an email address. Refusing to call Claude.');
}
return [{ json: { ...item, redacted_body: result.text, redaction_counts: result.counts } }];

const raw = $json.body ?? $json.data ?? $json.content ?? $json;
const text = typeof raw === 'string' ? raw : JSON.stringify(raw);
const start = text.indexOf('{'); const end = text.lastIndexOf('}');
if (start < 0) throw new Error('Claude did not return JSON. Check the HTTP node response path.');
const fields = JSON.parse(text.slice(start, end + 1));
const draft = String(fields.draft_body || '');
if (!/not sent/i.test(draft)) throw new Error('Draft is missing the not-sent line.');
return [{ json: { ...fields, sent: false, draft_status: 'draft_awaiting_approval' } }];
